MODULE mod_methane
    IMPLICIT NONE

    REAL(8), ALLOCATABLE, DIMENSION(:), SAVE :: CH4_2CO2_OXIDISATION_EMIS, &
                                            CH4_TIMEDEP_FOSSFUELFRACTION, CH4B_AIRMASS, CH4I_AIRMASS, CH4N_AIRMASS, CH4PF_AIRMASS, &
                                                CH4CLATH_AIRMASS, CH4_TAUOH_EFFECTIVE, CH4_DCDT, CH4_CBAR, &
                                                CH4_INVERSE_EMIS, CH4_CLATHRATE_POOL
    REAL(8), SAVE :: CH4_ADDEDSTRATH2O_PERCENT, CH4_RADEFF_WM2PERPPB
    REAL(8), SAVE :: CH4_TAUTOT_INIT, CH4_TAUOH_INIT, CH4_S, DELSS, DELTAU, CH4_ANOX, CH4_ACO, CH4_AVOC
    REAL(8), SAVE :: CH4_SCALEOHSENS, CH4_TAUOTHER, CH4_TAUSOIL, CH4_TAUSTRAT, CH4_TAUTROPCL, &
                     CH4_PPB2TGCH4, CH4_MIXBOXSIZE, &
                     CH4_NATEMISBUDGET, CH4_YRSTART_CONC, CH4_YRSTART_TEMP, CH4_NONSOILLIFETIME
    INTEGER, ALLOCATABLE, DIMENSION(:), SAVE :: CH4_TAUINITYEARSIDX
    INTEGER, SAVE :: CH4_INCLUDE_TEMPFEEDBACK, CH4_TAUFEEDBACK_BYNOXVOCCO, &
                     CH4_INCL_CH4OX, CH4_SWITCHFROMCONC2EMIS_YEAR, CH4_APPLYFOSSFUELFRACTION, &
                     CH4_CLATHRATEFEED_YRSTART, CH4_CLATHRATEFEED_APPLY, CH4_BUDGET_AVGYEARS
    REAL(8), SAVE :: CH4_FOSSFUELFRACTION, CH4_TAUTEMPSENSITIVITY, CH4_GWP, &
                     CH4_CLATHRATEFEED_ALPHA, CH4_CLATHRATEFEED_INIPOOL, CH4_CLATHRATE_CURRENTPOOL, &
                     CH4_FEED_YRSTART, CH4_LASTBUDGETYEAR
    REAL(8), save :: ch4_wetland_slope
CONTAINS

    !
    !   *****************************************************************************
    !   *****************************************************************************
    !   ****************   METHANE   ***********************************************
    !   *****************************************************************************
    !   *****************************************************************************

    !  CALL METHANE(CH4_INCLUDE_TEMPFEEDBACK , DAT_CH4_CONC%DATGLOBE(CURRENT_YEAR_IDX) , CH4_TOTEMIS , TROPOZ_DELTA_NOXEMIS ,  &
    !   TROPOZ_DELTA_COEMIS , TROPOZ_DELTA_NMVOCEMIS , NEXTYEAR_CH4_CONC , &
    !   CH4_TAUOH_INIT , CH4_TAUOH_EFFECTIVE(CURRENT_YEAR_IDX) , CH4_S , CH4_ANOX , CH4_ACO , CH4_AVOC , CH4_FEED_DELTATEMP)
    !
    SUBROUTINE METHANE(ICH4F, CPREV, E, DEN, DEC, DEV, CONC, &
                       TAU00, TAUOUT, S, AANOX, AACO, AAVOC, TEMP)

        USE MOD_LOGGING, only: logger
        use mod_maths, only: is_nan

        IMPLICIT NONE

        INTEGER, INTENT(IN) :: ICH4F
        REAL(8), INTENT(IN) :: TAU00, CPREV, AANOX, E, DEN, &
                               DEC, DEV, S, AAVOC, AACO, TEMP
        REAL(8), INTENT(OUT) :: TAUOUT, CONC
        REAL(8) :: TAU0, B, B00, AAA, X, U, DB1, B1, DB2, B2, TAUBAR, &
                   B3, DB3, B4, DB4, BBAR
        !
        !   ******************************************************************  **
        !
        !  METHANE MODEL USING PRATHER'S METHOD (FOR TAR)
        !  MODIFIED TO BEGIN IN 2000
        !  TAR METHOD :
        !   DOH / 0H  =  S * DB / B + AANOX * DEN  + AACO * DEC  + AAVOC * DEV   (TABLE 4.11)
        !   WHERE S  =  -0.32 (TABLE 4.11) (TABLE 4.2 GIVES -0.34 ??)
        !   DTAU / TAU  =  CH4_SCALEOHSENS  *  DOH / OH
        !   (CH4_SCALEOHSENS SHOULD BE =-1   = -1.145 ,  FROM DATA IN TABLE 4.2)
        !   CH4_SCALEOHSENS SPECIFIED IN METH3 COMMON BLOCK
        !
        !  NOTE THAT CONC AND TAU VALUES ARE END-OF-YEAR VALUES
        !
        !
        !  METHANE CONC PROJECTION.
        !
        ! NOTE THAT CH4_SCALEOHSENS IS THE SCALING FACTOR FOR THE DEPENDENCY OF THE METHANE LIFETIME
        ! UPON THE OH CONCENTRATION. THE (CHANGE IN) OH CONCENTRATION IS MODELLED BY
        !
        !  FIRST ITERATION
        !
        TAU0 = TAU00
        B = CPREV * CH4_PPB2TGCH4 * CH4_MIXBOXSIZE
        B00 = CH4_YRSTART_CONC * CH4_PPB2TGCH4 * CH4_MIXBOXSIZE
        AAA = DEXP(-CH4_SCALEOHSENS * (AANOX * DEN + AACO * DEC + AAVOC * DEV))
        X = -CH4_SCALEOHSENS * S
        U = TAU00 * AAA

        ! NOTE, 16 OCTOBER 2006: CH4_GAM HAS BEEN REPLACED BY -CH4_SCALEOHSENS FOR CONSISTENT AND MORE INTUITIVE NAMING CONVENTION

        ! MAKE SURE THAT THE RATIO BBAR/B00 IS NOT GOING TO DECREASE BELOW ZERO. THIS BUDGET RELATION
        ! BBAR/B00 INFLUENCES TROPOSPHERIC OZONE AND THEREBY THE LIFETIME OF CH4,
        ! I.E. INCREASING THE LIFETIME FOR HIGHER ATMOSPHERIC CH4 CONCENTRATIONS.
        ! THIS LOWER BOUNDING OF BBAR/B00 AT 1.0 ENSURES THAT THE LIFETIME
        ! ONLY CHANGES FOR METHANE CONCENTRATIONS ABOVE THE VALUE IN THE YEAR,
        ! IN WHICH THE FEEDBACKS ARE GOING TO START. OTHERWISE,
        ! A SUBSEQUENT FALL TO PRE-FEEDBACK-YEAR EMISSIONS WOULD RESULT IN EFFECTIVELY LOWER
        ! CONCENTRATIONS THAN APPARENT IN PRE-FEEDBACK-YEARS..
        !
        !  FIRST ITERATION
        !
        BBAR = B
        TAUBAR = U * (MAX(1.0D0, (BBAR / B00))**X)
        IF (ICH4F == 1) TAUBAR = TAU00 / (TAU00 / TAUBAR + CH4_TAUTEMPSENSITIVITY * TEMP)
        DB1 = E - BBAR / TAUBAR - BBAR / CH4_TAUOTHER
        B1 = B + DB1
        !
        !  SECOND ITERATION
        !
        BBAR = (B + B1) / 2.0D0
        TAUBAR = U * (MAX(1.0D0, (BBAR / B00))**X)
        TAUBAR = TAUBAR * (1.0D0 - 0.5D0 * X * DB1 / B)
        IF (ICH4F == 1) TAUBAR = TAU00 / (TAU00 / TAUBAR + CH4_TAUTEMPSENSITIVITY * TEMP)
        DB2 = E - BBAR / TAUBAR - BBAR / CH4_TAUOTHER
        B2 = B + DB2
        !
        !  THIRD ITERATION
        !
        BBAR = (B + B2) / 2.0D0
        TAUBAR = U * (MAX(1.0D0, (BBAR / B00))**X)
        TAUBAR = TAUBAR * (1.0D0 - 0.5D0 * X * DB2 / B)
        IF (ICH4F == 1) TAUBAR = TAU00 / (TAU00 / TAUBAR + CH4_TAUTEMPSENSITIVITY * TEMP)
        DB3 = E - BBAR / TAUBAR - BBAR / CH4_TAUOTHER
        B3 = B + DB3
        !
        !  FOURTH ITERATION
        !
        BBAR = (B + B3) / 2.0D0
        TAUBAR = U * (MAX(1.0D0, (BBAR / B00))**X)
        TAUBAR = TAUBAR * (1.0D0 - 0.5D0 * X * DB3 / B)
        IF (ICH4F == 1) TAUBAR = TAU00 / (TAU00 / TAUBAR + CH4_TAUTEMPSENSITIVITY * TEMP)
        DB4 = E - BBAR / TAUBAR - BBAR / CH4_TAUOTHER
        B4 = B + DB4
        !
        !  LIFETIME AND CONCENTRATION AT END OF STEP
        !
        TAUOUT = TAUBAR
        !WRITE(*,*) 'ATTENTION: METHANE LIFETIME ARTIFICALLY FIXED'
        !TAUOUT = TAU00
        CONC = B4 / (CH4_PPB2TGCH4 * CH4_MIXBOXSIZE)

        IF (is_nan(CONC)) THEN
            call logger % error('METHANE SUBROUTINE', 'Methane concentration is NaN')
        END IF

    END SUBROUTINE METHANE

    SUBROUTINE methane_calc_budget
        USE mod_years, only: startyear, nyears, allyears
        USE MOD_DATASTORE, only: DAT_CH4B_EMIS, DAT_CH4B_EMIS, DAT_CH4I_EMIS, DAT_CH4N_EMIS, DAT_CH4_CONC, &
                                 dat_ch4clathrate_emis, DAT_CH4PF_EMIS
        USE mod_logging, only: logger

        integer i

        ! THIS SECTION CALCULATES THE NATURAL METHANE EMISSIONS THAT HAVE TO BE ASSUMED IN ORDER TO
        ! MATCH THE BUDGETING PERIOD'S CH4 CONCENTRATIONS WITH THE GIVEN TOTAL LIFETIME TAU.
        ! THE BUDGETING PERIOD IS DETERMINED BY THE CH4_LASTBUDGETYEAR VARIABLE AND THE CH4N2O_BUDGET_AVGYEARS LENGTH
        !
        ! THESE BUDGET EQUATIONS ARE OF THE FORM:
        ! EMISSION_NATURAL = CONVERSIONFACTOR( DC / DT + CONC / TAU1 + CONC / TAU2) -
        ! EMISSION_HUMAN_BIO&IND&NAT-FOSSIL(STARTOFYEAR - THEREFORE MEAN (A(T) + A(T + 1)) / 2))
        ! WHEREAS ON THE RIGHT HAND SIDE ALL ARRAYS ARE GIVEN FOR A WINDOW OF ,  FOR EXAMPLE ,  10 YEARS. THUS ,
        ! THERE IS AN ADDITIONAL DENOMINATOR ,  THE WINDOW SIZE 'XXX_TAUINITYEARSIDX'
        !(WHERE XXX STANDS FOR THE GAS NAME ,  E.G. CH4 OR N2O).

        ! THE (PARTIAL) METHANE LIFETIME DUE TO SOIL AND STRATOSPHERIC SINKS
        ! ADAPTED FROM THE INITIAL
        IF (((CH4_TAUSOIL /= 0.0D0) .AND. (CH4_TAUSTRAT /= 0.0D0)) .AND. (CH4_TAUTROPCL /= 0.0D0)) THEN
            CH4_TAUOTHER = 1.0D0 / (1.0D0 / CH4_TAUSOIL + 1.0D0 / CH4_TAUSTRAT + 1.0D0 / CH4_TAUTROPCL)
        ELSEIF ((CH4_TAUSOIL /= 0.0D0) .AND. (CH4_TAUSTRAT /= 0.0D0)) THEN
            CH4_TAUOTHER = 1.0D0 / (1.0D0 / CH4_TAUSOIL + 1.0D0 / CH4_TAUSTRAT)
        ELSEIF ((CH4_TAUSOIL /= 0.0D0) .AND. (CH4_TAUTROPCL /= 0.0D0)) THEN
            CH4_TAUOTHER = 1.0D0 / (1.0D0 / CH4_TAUSOIL + 1.0D0 / CH4_TAUTROPCL)
        ELSEIF ((CH4_TAUSTRAT /= 0.0D0) .AND. (CH4_TAUTROPCL /= 0.0D0)) THEN
            CH4_TAUOTHER = 1.0D0 / (1.0D0 / CH4_TAUSTRAT + 1.0D0 / CH4_TAUTROPCL)
        ELSEIF (CH4_TAUSOIL /= 0.0D0) THEN
            CH4_TAUOTHER = CH4_TAUSOIL
        ELSEIF (CH4_TAUOTHER /= 0.0D0) THEN
            CH4_TAUOTHER = CH4_TAUOTHER
        ELSEIF (CH4_TAUTROPCL /= 0.0D0) THEN
            CH4_TAUOTHER = CH4_TAUTROPCL
        ELSE
            WRITE (*, *) &
                'ERROR: EITHER METHANE LIFETIME CH4_TAUSOIL OR CH4_TAUSTRAT OR CH4_TAUTROPCL HAS TO BE DIFFERENT FROM ZERO'
        END IF

        ! CONVERT THE CH4_TAUTOT_INIT TO THE CH4_TAUOH_INIT

        CH4_TAUOH_INIT = 1.0D0 / (1.0D0 / CH4_TAUTOT_INIT - 1.0D0 / CH4_TAUOTHER)

        ! CALCULATE THE DC / DT FOR MIDYEARS OVER THE LAST TEN YEARS OF THE PROVIDED CONCENTRATIONS

        ! ADJUST THE LASTBUDGETYEAR VARIABLE ,  IF OUTSIDE THE RANGE OF PREDEFINED CONCENTRATIONS...
        IF (DAT_CH4_CONC % LASTYEAR <= INT(CH4_LASTBUDGETYEAR)) CH4_LASTBUDGETYEAR = REAL(DAT_CH4_CONC % LASTYEAR, 8)

        IF (DAT_CH4_CONC % FIRSTYEAR > INT(CH4_LASTBUDGETYEAR) - CH4_BUDGET_AVGYEARS + 1) &
            CH4_LASTBUDGETYEAR = REAL(DAT_CH4_CONC % FIRSTYEAR) + CH4_BUDGET_AVGYEARS
        ! CHECK AS WELL WHETHER WTIHIN BOUNDS OF SIMULATION RUN
        IF (CH4_LASTBUDGETYEAR - CH4_BUDGET_AVGYEARS + 1 < STARTYEAR) CH4_LASTBUDGETYEAR = &
            STARTYEAR + CH4_BUDGET_AVGYEARS
        IF (CH4_LASTBUDGETYEAR > ALLYEARS(NYEARS)) CH4_LASTBUDGETYEAR = ALLYEARS(NYEARS)

        ! CREATE INDEXES WITH LAST YEARS OF CONCENTRATIONS
        DO I = 1, SIZE(CH4_TAUINITYEARSIDX)
            CH4_TAUINITYEARSIDX(I) = INT(CH4_LASTBUDGETYEAR) - STARTYEAR - SIZE(CH4_TAUINITYEARSIDX) + 1 + I
        END DO

        ! CALCULATE ARRAY WITH ANNUAL DIFFERENCES & MID-YEAR MEAN CONCENTRATIONS
        CH4_DCDT(1:NYEARS - 1) = DAT_CH4_CONC % DATGLOBE(2:NYEARS) - DAT_CH4_CONC % DATGLOBE(1:NYEARS - 1)
        CH4_CBAR(1:NYEARS - 1) = (DAT_CH4_CONC % DATGLOBE(2:NYEARS) + DAT_CH4_CONC % DATGLOBE(1:NYEARS - 1)) &
                                 / 2.0D0

        ! NOTE THAT NAT EMISSIONS ARE MOST LIKELY ZERO ,  IF NO FILE_XXN_EMIS INPUT FILE NAME IS SPECIFIED.
        ! NOTE THAT PERMAFROST AND CLATHRATE EMISSIONS ARE NOT YET CALCULATED AT THIS STAGE, THUS ENTER THIS EQUATION AS ZERO.

        CH4_NATEMISBUDGET = CH4_PPB2TGCH4 * CH4_MIXBOXSIZE * (SUM(CH4_DCDT(CH4_TAUINITYEARSIDX - 1)) + &
                                                              SUM(CH4_CBAR(CH4_TAUINITYEARSIDX - 1)) / CH4_TAUOH_INIT + &
                                                              SUM(CH4_CBAR(CH4_TAUINITYEARSIDX - 1)) / CH4_TAUOTHER) / &
                            REAL(SIZE(CH4_TAUINITYEARSIDX), 8) - &
                            (SUM(DAT_CH4I_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX)) + &
                             SUM(DAT_CH4I_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX - 1)) + &
                             SUM(DAT_CH4B_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX)) + &
                             SUM(DAT_CH4B_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX - 1)) + &
                             SUM(DAT_CH4N_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX)) + &
                             SUM(DAT_CH4N_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX - 1)) + &
                             SUM(DAT_CH4CLATHRATE_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX)) + &
                             SUM(DAT_CH4CLATHRATE_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX - 1)) + &
                             SUM(DAT_CH4PF_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX)) + &
                             SUM(DAT_CH4PF_EMIS % DATGLOBE(CH4_TAUINITYEARSIDX - 1))) / &
                            2.0D0 / REAL(SIZE(CH4_TAUINITYEARSIDX), 8)

        ! UPDATE THE DAT_CH4N_EMIS STRUCTURE BY ADDING THIS CONSTANT NATURAL EMISSION TO IT.
        DAT_CH4N_EMIS % DATGLOBE = DAT_CH4N_EMIS % DATGLOBE + CH4_NATEMISBUDGET
        DAT_CH4N_EMIS % DATBOX = DAT_CH4N_EMIS % DATBOX + DAT_CH4N_EMIS % FRACTIONSBOX * CH4_NATEMISBUDGET

        ! MAKE SURE THAT THE CLATHRATES FEEDBACK STARTING YEAR IS COMING AFTER THE CH4_LASTBUDGETYEAR

        IF (CH4_CLATHRATEFEED_YRSTART <= CH4_LASTBUDGETYEAR) THEN
            CH4_CLATHRATEFEED_YRSTART = int(CH4_LASTBUDGETYEAR) + 1

            call logger % warning('jumponstage', 'Your clathrate starting date has to'// &
                                  ' be later than the date when the natural emission budget is derived.')
        END IF
    END SUBROUTINE methane_calc_budget
END MODULE mod_methane
